def encode(data: bytes) -> bytes:
    table = list(range(256))
    out = bytearray(len(data))
    for pos, b in enumerate(data):
        i = table.index(b)
        out[pos] = i
        if i:
            del table[i]
            table.insert(0, b)
    return bytes(out)


